 43	public class Api {
 44	    private static final String CSV = "text/csv; charset=utf-8";
 45	
 46	    private final ReservationService service;
 47	    private final Reports reports;
 48	    private final ObjectMapper mapper = new ObjectMapper()
 49	            .registerModule(new JavaTimeModule())
 50	            .disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS);
 51	
 52	    public Api(ReservationService service, Reports reports) {
 53	        this.service = service;
 54	        this.reports = reports;
 55	    }
 56	
 57	    public Javalin create() {
 58	        Javalin app = Javalin.create(config -> {
 59	            config.showJavalinBanner = false;
 60	            config.jsonMapper(new JavalinJackson(mapper, false));
 61	        });
 62	
 63	        app.get("/rooms", ctx -> ctx.json(RoomCatalog.all().stream().map(Api::roomView).toList()));
 64	        app.post("/reservations", ctx -> ctx.status(201)
 65	                .json(ReservationView.of(service.create(ReservationRequest.parse(mapper, ctx.body())))));
 66	        app.get("/reservations/{id}", ctx -> ctx.json(ReservationView.of(service.get(id(ctx)))));
 67	        app.post("/reservations/{id}/confirmation", ctx -> ctx.json(ReservationView.of(service.confirm(id(ctx)))));
 68	        app.post("/reservations/{id}/cancellation", ctx -> ctx.json(ReservationView.of(service.cancel(id(ctx)))));
 69	        app.post("/reservations/{id}/check-in", ctx -> ctx.json(ReservationView.of(service.checkIn(id(ctx)))));
 70	        app.post("/reservations/{id}/check-out", ctx -> ctx.json(service.checkOut(id(ctx))));
 71	        app.get("/reservations/{id}/document", ctx -> ctx.json(service.document(id(ctx))));
 72	        app.get("/messages", ctx -> ctx.json(service.messages()));
 73	        app.get("/reports/occupancy", ctx -> ctx.contentType(CSV).result(reports.occupancy(queryDate(ctx))));
 74	        app.get("/reports/revenue", ctx -> ctx.contentType(CSV).result(reports.revenue(queryMonth(ctx))));
 75	
 76	        app.exception(AppException.class, (e, ctx) -> error(ctx, e.code().status(), e.code().name(), e.getMessage()));
 77	        app.exception(Exception.class, (e, ctx) -> {
 78	            e.printStackTrace();
 79	            error(ctx, 500, "INTERNAL_ERROR", "Erro interno");
 80	        });
 81	        return app;
 82	    }
 83	
 84	    private static void error(Context ctx, int status, String code, String message) {
 85	        ctx.status(status).json(Map.of("error", code, "message", message));
 86	    }
 87	
 88	    private static Map<String, Object> roomView(Room room) {
 89	        Map<String, Object> view = new LinkedHashMap<>();
 90	        view.put("number", room.number());
 91	        view.put("type", room.type());
 92	        view.put("capacity", room.type().capacity());
 93	        view.put("nightlyRate", room.type().nightlyRate());
 94	        return view;
 95	    }
