 97	    private static long id(Context ctx) {
 98	        try {
 99	            return Long.parseLong(ctx.pathParam("id"));
100	        } catch (NumberFormatException e) {
101	            throw new AppException(ErrorCode.RESERVATION_NOT_FOUND, "Reserva inexistente");
102	        }
103	    }
104	
105	    private static LocalDate queryDate(Context ctx) {
106	        try {
107	            return LocalDate.parse(String.valueOf(ctx.queryParam("date")));
108	        } catch (DateTimeParseException e) {
109	            throw new AppException(ErrorCode.INVALID_REQUEST, "Parâmetro date inválido (use AAAA-MM-DD)");
110	        }
