123	import com.fasterxml.jackson.core.JsonProcessingException;
124	import com.fasterxml.jackson.databind.JsonNode;
125	import com.fasterxml.jackson.databind.ObjectMapper;
126	import pousada.domain.AppException;
127	import pousada.domain.ErrorCode;
128	import pousada.service.NewReservation;
129	
130	import java.time.LocalDate;
131	import java.time.format.DateTimeParseException;
132	
133	/** Lê e valida o corpo do POST /reservations. */
134	final class ReservationRequest {
135	    private final JsonNode body;
136	
137	    private ReservationRequest(JsonNode body) {
138	        this.body = body;
139	    }
140	
141	    static NewReservation parse(ObjectMapper mapper, String raw) {
142	        JsonNode node;
143	        try {
144	            node = mapper.readTree(raw);
145	        } catch (JsonProcessingException | IllegalArgumentException e) {
146	            throw invalid("O corpo não é um JSON válido");
147	        }
148	        if (node == null || !node.isObject()) {
149	            throw invalid("O corpo deve ser um objeto JSON");
150	        }
151	        return new ReservationRequest(node).build();
152	    }
153	
154	    private NewReservation build() {
155	        LocalDate checkIn = date("checkIn");
156	        LocalDate checkOut = date("checkOut");
157	        int guests = integer("guests");
158	        if (!checkOut.isAfter(checkIn)) {
159	            throw invalid("A saída deve ser depois da entrada");
160	        }
161	        if (guests < 1) {
162	            throw invalid("É preciso pelo menos um hóspede");
163	        }
164	        JsonNode company = body.get("companyCode");
165	        String companyCode = company != null && company.isTextual() ? company.asText().trim() : null;
166	        return new NewReservation(integer("roomNumber"), text("guestName"), text("guestEmail"), text("guestCpf"),
167	                checkIn, checkOut, guests, text("ratePlan"), companyCode);
168	    }
169	
170	    private String text(String field) {
171	        JsonNode node = body.get(field);
172	        if (node == null || !node.isTextual() || node.asText().isBlank()) {
173	            throw invalid("Campo obrigatório ausente ou inválido: " + field);
174	        }
175	        return node.asText().trim();
176	    }
177	
178	    private int integer(String field) {
179	        JsonNode node = body.get(field);
180	        if (node == null || !node.isIntegralNumber() || !node.canConvertToInt()) {
181	            throw invalid("Campo obrigatório ausente ou inválido: " + field);
182	        }
183	        return node.asInt();
184	    }
185	
186	    private LocalDate date(String field) {
187	        try {
188	            return LocalDate.parse(text(field));
189	        } catch (DateTimeParseException e) {
190	            throw invalid("Data inválida em " + field + " (use AAAA-MM-DD)");
191	        }
192	    }
193	
194	    private static AppException invalid(String message) {
195	        return new AppException(ErrorCode.INVALID_REQUEST, message);
196	    }
197	}
