255	package pousada.service;
256	
257	import pousada.domain.AppException;
258	import pousada.domain.ErrorCode;
259	import pousada.domain.Message;
260	import pousada.domain.Money;
261	import pousada.domain.Receipt;
262	import pousada.domain.ReceiptText;
263	import pousada.domain.Reservation;
264	import pousada.domain.ReservationStatus;
265	import pousada.domain.Room;
266	import pousada.domain.RoomCatalog;
267	import pousada.plan.Pricing;
268	import pousada.plan.RatePlan;
269	import pousada.plan.RatePlans;
270	import pousada.plan.Stay;
271	
272	import java.util.List;
273	import java.util.function.Consumer;
274	
275	public class ReservationService {
276	    private final ReservationRepository repository;
277	
278	    public ReservationService(ReservationRepository repository) {
279	        this.repository = repository;
280	    }
281	
282	    public Reservation create(NewReservation request) {
283	        Room room = RoomCatalog.find(request.roomNumber())
284	                .orElseThrow(() -> new AppException(ErrorCode.ROOM_NOT_FOUND, "Quarto inexistente"));
285	        RatePlan plan = RatePlans.byCode(request.ratePlan());
286	        Stay stay = new Stay(room, request.checkIn(), request.checkOut(), request.companyCode());
287	        Pricing pricing = plan.quote(stay);
288	        if (request.guests() > room.type().capacity()) {
289	            throw new AppException(ErrorCode.CAPACITY_EXCEEDED,
290	                    "O quarto " + room.number() + " comporta até " + room.type().capacity() + " pessoas");
291	        }
292	        Reservation draft = new Reservation(0, room, request.guestName(), request.guestEmail(),
293	                request.guestCpf(), request.checkIn(), request.checkOut(), request.guests(), plan, stay.nights(),
294	                pricing.subtotal(), pricing.discount(), pricing.total(), ReservationStatus.PENDING,
295	                Money.ZERO, null);
296	        return repository.insert(draft);
297	    }
298	
299	    public Reservation get(long id) {
300	        return repository.find(id)
301	                .orElseThrow(() -> new AppException(ErrorCode.RESERVATION_NOT_FOUND, "Reserva inexistente"));
302	    }
303	
304	    public Reservation confirm(long id) {
305	        return transition(id, Reservation::confirm, r -> {
306	            Receipt receipt = r.receipt();
307	            return List.of(Message.email(r.guestEmail(), ReceiptText.CONFIRMATION_SUBJECT,
308	                    ReceiptText.confirmationEmail(receipt)));
309	        });
310	    }
311	
312	    public Reservation cancel(long id) {
313	        return transition(id, Reservation::cancel);
314	    }
315	
316	    public Reservation checkIn(long id) {
317	        return transition(id, Reservation::checkIn);
318	    }
319	
320	    public Receipt checkOut(long id) {
321	        return transition(id, Reservation::checkOut).receipt();
322	    }
323	
324	    public Receipt document(long id) {
325	        return get(id).receipt();
326	    }
327	
328	    public List<Message> messages() {
329	        return repository.messages();
330	    }
331	
332	    private Reservation transition(long id, Consumer<Reservation> action) {
333	        return transition(id, action, r -> List.of());
334	    }
335	
336	    private Reservation transition(long id, Consumer<Reservation> action,
337	                                   java.util.function.Function<Reservation, List<Message>> outgoing) {
338	        Reservation reservation = get(id);
339	        ReservationStatus before = reservation.status();
340	        action.accept(reservation);
341	        repository.update(reservation, before, outgoing.apply(reservation));
342	        return reservation;
343	    }
344	}

