235	
236	    /** Guarda a reserva nova e devolve com o id; ROOM_UNAVAILABLE se o quarto já estiver ocupado numa das noites. */
237	    Reservation insert(Reservation draft);
238	
239	    Optional<Reservation> find(long id);
240	
241	    /**
242	     * Grava o novo estado da reserva (e as mensagens, na mesma operação) se ela ainda estiver em {@code expected};
243	     * senão, OPERATION_NOT_ALLOWED.
244	     */
245	    void update(Reservation reservation, ReservationStatus expected, List<Message> messages);
246	
247	    List<Message> messages();
248	
249	    /** Reservas pagas que ocupam um quarto na noite. */
250	    List<Reservation> paidOnNight(LocalDate night);
251	
252	    /** Reservas cuja entrada está no intervalo [from, to]. */
253	    List<Reservation> checkInBetween(LocalDate from, LocalDate to);
