    26	    public Reservation(long id, Room room, String guestName, String guestEmail, String guestCpf,
    27	                       LocalDate checkIn, LocalDate checkOut, int guests, RatePlan ratePlan, int nights,
    28	                       BigDecimal subtotal, BigDecimal discount, BigDecimal total,
    29	                       ReservationStatus status, BigDecimal amountPaid, BigDecimal refund) {
