    50	                nights, subtotal, discount, total, status, amountPaid, refund);
    51	    }
    52	
    53	    public void confirm() {
    54	        require(ReservationStatus.PENDING);
    55	        status = ReservationStatus.CONFIRMED;
    56	        amountPaid = total;
    57	    }
    58	
    59	    public void checkIn() {
    60	        require(ReservationStatus.CONFIRMED);
    61	        status = ReservationStatus.CHECKED_IN;
