     3	import com.zaxxer.hikari.HikariConfig;
     4	import com.zaxxer.hikari.HikariDataSource;
     5	
     6	import javax.sql.DataSource;
     7	import java.sql.Connection;
     8	import java.sql.SQLException;
     9	import java.sql.Statement;
    10	
    11	public final class Database {
    12	    private static final int CONNECT_ATTEMPTS = 30;
    13	
    14	    private Database() {
    15	    }
    16	
    17	    public static DataSource connect(String url, String user, String password) {
    18	        HikariConfig config = new HikariConfig();
    19	        config.setJdbcUrl(url);
    20	        config.setUsername(user);
    21	        config.setPassword(password);
    22	        config.setMaximumPoolSize(10);
    23	        config.setInitializationFailTimeout(-1);
    24	        HikariDataSource dataSource = new HikariDataSource(config);
    25	        createSchema(dataSource);
    26	        return dataSource;
    27	    }
    28	
    29	    private static void createSchema(DataSource dataSource) {
    30	        for (int attempt = 1; ; attempt++) {
    31	            try (Connection c = dataSource.getConnection(); Statement s = c.createStatement()) {
    32	                s.execute("SELECT pg_advisory_lock(1)");
    33	                try {
    34	                    s.execute("""
    35	                            CREATE TABLE IF NOT EXISTS reservations (
    36	                                id BIGSERIAL PRIMARY KEY,
    37	                                room_number INT NOT NULL,
    38	                                guest_name TEXT NOT NULL,
    39	                                guest_email TEXT NOT NULL,
    40	                                guest_cpf TEXT NOT NULL,
    41	                                check_in DATE NOT NULL,
    42	                                check_out DATE NOT NULL,
    43	                                guests INT NOT NULL,
    44	                                rate_plan TEXT NOT NULL,
    45	                                nights INT NOT NULL,
    46	                                subtotal NUMERIC(12,2) NOT NULL,
    47	                                discount NUMERIC(12,2) NOT NULL,
    48	                                total NUMERIC(12,2) NOT NULL,
    49	                                status TEXT NOT NULL,
    50	                                amount_paid NUMERIC(12,2) NOT NULL,
    51	                                refund NUMERIC(12,2)
    52	                            )""");
    53	                    s.execute("""
    54	                            CREATE TABLE IF NOT EXISTS messages (
    55	                                id BIGSERIAL PRIMARY KEY,
    56	                                channel TEXT NOT NULL,
    57	                                recipient TEXT NOT NULL,
    58	                                subject TEXT NOT NULL,
    59	                                body TEXT NOT NULL
    60	                            )""");
    61	                } finally {
    62	                    s.execute("SELECT pg_advisory_unlock(1)");
    63	                }
    64	                return;
    65	            } catch (SQLException e) {
    66	                if (attempt >= CONNECT_ATTEMPTS) {
    67	                    throw new IllegalStateException("Não foi possível preparar o banco", e);
    68	                }
    69	                try {
    70	                    Thread.sleep(1000);
    71	                } catch (InterruptedException ie) {
    72	                    Thread.currentThread().interrupt();
    73	                    throw new IllegalStateException(ie);
    74	                }
    75	            }
    76	        }
    77	    }
    78	}
    79	package pousada.infra;
