    87	import pousada.domain.RoomCatalog;
    88	import pousada.plan.RatePlans;
    89	import pousada.service.ReservationRepository;
    90	
    91	import javax.sql.DataSource;
    92	import java.sql.Connection;
    93	import java.sql.Date;
    94	import java.sql.PreparedStatement;
    95	import java.sql.ResultSet;
    96	import java.sql.SQLException;
    97	import java.time.LocalDate;
    98	import java.util.ArrayList;
    99	import java.util.List;
   100	import java.util.Optional;
   101	
   102	public class PostgresReservationRepository implements ReservationRepository {
   103	    private static final String COLUMNS = "id, room_number, guest_name, guest_email, guest_cpf, check_in, check_out, "
   104	            + "guests, rate_plan, nights, subtotal, discount, total, status, amount_paid, refund";
   105	
   106	    private final DataSource dataSource;
   107	
   108	    public PostgresReservationRepository(DataSource dataSource) {
   109	        this.dataSource = dataSource;
   110	    }
   111	
   112	    @Override
   113	    public Reservation insert(Reservation r) {
   114	        try (Connection c = dataSource.getConnection()) {
   115	            c.setAutoCommit(false);
   116	            try {
   117	                // serializa as reservas do mesmo quarto até o fim da transação
   118	                try (PreparedStatement lock = c.prepareStatement("SELECT pg_advisory_xact_lock(?)")) {
   119	                    lock.setLong(1, 1_000_000L + r.room().number());
   120	                    lock.execute();
   121	                }
   122	                try (PreparedStatement overlap = c.prepareStatement(
   123	                        "SELECT 1 FROM reservations WHERE room_number = ? AND status <> 'CANCELLED' "
   124	                                + "AND check_in < ? AND check_out > ? LIMIT 1")) {
   125	                    overlap.setInt(1, r.room().number());
   126	                    overlap.setDate(2, Date.valueOf(r.checkOutDate()));
   127	                    overlap.setDate(3, Date.valueOf(r.checkInDate()));
   128	                    try (ResultSet rs = overlap.executeQuery()) {
   129	                        if (rs.next()) {
   130	                            throw new AppException(ErrorCode.ROOM_UNAVAILABLE,
   131	                                    "O quarto já está reservado em alguma das noites");
   132	                        }
   133	                    }
   134	                }
   135	                long id;
   136	                try (PreparedStatement insert = c.prepareStatement(
   137	                        "INSERT INTO reservations (room_number, guest_name, guest_email, guest_cpf, check_in, "
   138	                                + "check_out, guests, rate_plan, nights, subtotal, discount, total, status, "
   139	                                + "amount_paid, refund) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?) RETURNING id")) {
   140	                    insert.setInt(1, r.room().number());
   141	                    insert.setString(2, r.guestName());
   142	                    insert.setString(3, r.guestEmail());
   143	                    insert.setString(4, r.guestCpf());
   144	                    insert.setDate(5, Date.valueOf(r.checkInDate()));
   145	                    insert.setDate(6, Date.valueOf(r.checkOutDate()));
   146	                    insert.setInt(7, r.guests());
   147	                    insert.setString(8, r.ratePlan().code());
   148	                    insert.setInt(9, r.nights());
   149	                    insert.setBigDecimal(10, r.subtotal());
   150	                    insert.setBigDecimal(11, r.discount());
   151	                    insert.setBigDecimal(12, r.total());
   152	                    insert.setString(13, r.status().name());
   153	                    insert.setBigDecimal(14, r.amountPaid());
   154	                    insert.setBigDecimal(15, r.refund());
   155	                    try (ResultSet rs = insert.executeQuery()) {
   156	                        rs.next();
   157	                        id = rs.getLong(1);
   158	                    }
   159	                }
   160	                c.commit();
   161	                return r.withId(id);
   162	            } catch (RuntimeException | SQLException e) {
   163	                c.rollback();
   164	                throw e;
   165	            }
   166	        } catch (SQLException e) {
   167	            throw new IllegalStateException(e);
   168	        }
   169	    }
   170	
   171	    @Override
   172	    public Optional<Reservation> find(long id) {
   173	        List<Reservation> found = query("SELECT " + COLUMNS + " FROM reservations WHERE id = ?", ps -> ps.setLong(1, id));
   174	        return found.stream().findFirst();
   175	    }
   176	
   177	    @Override
   178	    public void update(Reservation r, ReservationStatus expected, List<Message> messages) {
   179	        try (Connection c = dataSource.getConnection()) {
   180	            c.setAutoCommit(false);
   181	            try {
   182	                int changed;
   183	                try (PreparedStatement ps = c.prepareStatement(
   184	                        "UPDATE reservations SET status = ?, amount_paid = ?, refund = ? WHERE id = ? AND status = ?")) {
   185	                    ps.setString(1, r.status().name());
   186	                    ps.setBigDecimal(2, r.amountPaid());
   187	                    ps.setBigDecimal(3, r.refund());
   188	                    ps.setLong(4, r.id());
   189	                    ps.setString(5, expected.name());
   190	                    changed = ps.executeUpdate();
   191	                }
   192	                if (changed == 0) {
   193	                    throw new AppException(ErrorCode.OPERATION_NOT_ALLOWED,
   194	                            "A situação da reserva mudou; operação não permitida");
   195	                }
   196	                for (Message m : messages) {
   197	                    try (PreparedStatement ps = c.prepareStatement(
   198	                            "INSERT INTO messages (channel, recipient, subject, body) VALUES (?,?,?,?)")) {
   199	                        ps.setString(1, m.channel().name());
   200	                        ps.setString(2, m.to());
   201	                        ps.setString(3, m.subject());
   202	                        ps.setString(4, m.body());
   203	                        ps.executeUpdate();
   204	                    }
   205	                }
   206	                c.commit();
   207	            } catch (RuntimeException | SQLException e) {
   208	                c.rollback();
   209	                throw e;
   210	            }
   211	        } catch (SQLException e) {
   212	            throw new IllegalStateException(e);
   213	        }
   214	    }
   215	
   216	    @Override
   217	    public List<Message> messages() {
   218	        List<Message> result = new ArrayList<>();
   219	        try (Connection c = dataSource.getConnection();
   220	             PreparedStatement ps = c.prepareStatement(
   221	                     "SELECT id, channel, recipient, subject, body FROM messages ORDER BY id");
   222	             ResultSet rs = ps.executeQuery()) {
   223	            while (rs.next()) {
   224	                result.add(new Message(rs.getLong(1), Channel.valueOf(rs.getString(2)), rs.getString(3),
   225	                        rs.getString(4), rs.getString(5)));
   226	            }
   227	            return result;
   228	        } catch (SQLException e) {
   229	            throw new IllegalStateException(e);
   230	        }
   231	    }
   232	
   233	    @Override
   234	    public List<Reservation> paidOnNight(LocalDate night) {
   235	        return query("SELECT " + COLUMNS + " FROM reservations WHERE status IN ('CONFIRMED','CHECKED_IN','CHECKED_OUT') "
   236	                + "AND check_in <= ? AND check_out > ?", ps -> {
   237	            ps.setDate(1, Date.valueOf(night));
   238	            ps.setDate(2, Date.valueOf(night));
   239	        });
   240	    }
   241	
   242	    @Override
   243	    public List<Reservation> checkInBetween(LocalDate from, LocalDate to) {
   244	        return query("SELECT " + COLUMNS + " FROM reservations WHERE check_in BETWEEN ? AND ?", ps -> {
   245	            ps.setDate(1, Date.valueOf(from));
   246	            ps.setDate(2, Date.valueOf(to));
   247	        });
   248	    }
   249	
   250	    private interface Binder {
   251	        void bind(PreparedStatement ps) throws SQLException;
   252	    }
   253	
   254	    private List<Reservation> query(String sql, Binder binder) {
   255	        try (Connection c = dataSource.getConnection(); PreparedStatement ps = c.prepareStatement(sql)) {
   256	            binder.bind(ps);
   257	            try (ResultSet rs = ps.executeQuery()) {
   258	                List<Reservation> result = new ArrayList<>();
   259	                while (rs.next()) {
   260	                    result.add(read(rs));
   261	                }
   262	                return result;
   263	            }
   264	        } catch (SQLException e) {
   265	            throw new IllegalStateException(e);
   266	        }
   267	    }
   268	
   269	    private Reservation read(ResultSet rs) throws SQLException {
   270	        return new Reservation(rs.getLong("id"),
   271	                RoomCatalog.find(rs.getInt("room_number")).orElseThrow(),
   272	                rs.getString("guest_name"), rs.getString("guest_email"), rs.getString("guest_cpf"),
   273	                rs.getDate("check_in").toLocalDate(), rs.getDate("check_out").toLocalDate(),
   274	                rs.getInt("guests"), RatePlans.byCode(rs.getString("rate_plan")), rs.getInt("nights"),
   275	                rs.getBigDecimal("subtotal"), rs.getBigDecimal("discount"), rs.getBigDecimal("total"),
   276	                ReservationStatus.valueOf(rs.getString("status")), rs.getBigDecimal("amount_paid"),
   277	                rs.getBigDecimal("refund"));
   278	    }
   279	}
