   112	    @Override
   113	    public Reservation insert(Reservation r) {
   114	        try (Connection c = dataSource.getConnection()) {
   115	            c.setAutoCommit(false);
   116	            try {
   117	                // serializa as reservas do mesmo quarto até o fim da transação
   118	                try (PreparedStatement lock = c.prepareStatement("SELECT pg_advisory_xact_lock(?)")) {
   119	                    lock.setLong(1, 1_000_000L + r.room().number());
   120	                    lock.execute();
   121	                }
   122	                try (PreparedStatement overlap = c.prepareStatement(
   123	                        "SELECT 1 FROM reservations WHERE room_number = ? AND status <> 'CANCELLED' "
   124	                                + "AND check_in < ? AND check_out > ? LIMIT 1")) {
   125	                    overlap.setInt(1, r.room().number());
   126	                    overlap.setDate(2, Date.valueOf(r.checkOutDate()));
   127	                    overlap.setDate(3, Date.valueOf(r.checkInDate()));
   128	                    try (ResultSet rs = overlap.executeQuery()) {
   129	                        if (rs.next()) {
   130	                            throw new AppException(ErrorCode.ROOM_UNAVAILABLE,
   131	                                    "O quarto já está reservado em alguma das noites");
   132	                        }
   133	                    }
   134	                }
   135	                long id;
   136	                try (PreparedStatement insert = c.prepareStatement(
   137	                        "INSERT INTO reservations (room_number, guest_name, guest_email, guest_cpf, check_in, "
   138	                                + "check_out, guests, rate_plan, nights, subtotal, discount, total, status, "
   139	                                + "amount_paid, refund) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?) RETURNING id")) {
   140	                    insert.setInt(1, r.room().number());
   141	                    insert.setString(2, r.guestName());
   142	                    insert.setString(3, r.guestEmail());
   143	                    insert.setString(4, r.guestCpf());
   144	                    insert.setDate(5, Date.valueOf(r.checkInDate()));
   145	                    insert.setDate(6, Date.valueOf(r.checkOutDate()));
   146	                    insert.setInt(7, r.guests());
   147	                    insert.setString(8, r.ratePlan().code());
   148	                    insert.setInt(9, r.nights());
   149	                    insert.setBigDecimal(10, r.subtotal());
   150	                    insert.setBigDecimal(11, r.discount());
   151	                    insert.setBigDecimal(12, r.total());
   152	                    insert.setString(13, r.status().name());
   153	                    insert.setBigDecimal(14, r.amountPaid());
   154	                    insert.setBigDecimal(15, r.refund());
   155	                    try (ResultSet rs = insert.executeQuery()) {
   156	                        rs.next();
   157	                        id = rs.getLong(1);
   158	                    }
