 17	
 18	import static org.junit.jupiter.api.Assertions.assertEquals;
 19	import static org.junit.jupiter.api.Assertions.assertTrue;
 20	
 21	class ApiTest {
 22	    static Javalin app;
 23	    static String base;
 24	    static final HttpClient http = HttpClient.newHttpClient();
 25	    static final ObjectMapper json = new ObjectMapper()
 26	            .enable(com.fasterxml.jackson.databind.DeserializationFeature.USE_BIG_DECIMAL_FOR_FLOATS);
 27	
 28	    @BeforeAll
 29	    static void start() {
 30	        InMemoryRepository repo = new InMemoryRepository();
 31	        app = new Api(new ReservationService(repo), new Reports(repo)).create().start(0);
 32	        base = "http://localhost:" + app.port();
 33	    }
 34	
 35	    @AfterAll
 36	    static void stop() {
 37	        app.stop();
 38	    }
 39	
 40	    record Res(int status, String body) {
 41	        JsonNode json() throws Exception {
 42	            return ApiTest.json.readTree(body);
 43	        }
 44	    }
 45	
 46	    static Res send(String method, String path, String body) throws Exception {
 47	        HttpRequest.Builder b = HttpRequest.newBuilder(URI.create(base + path));
 48	        b.method(method, body == null ? HttpRequest.BodyPublishers.noBody() : HttpRequest.BodyPublishers.ofString(body));
 49	        HttpResponse<String> r = http.send(b.build(), HttpResponse.BodyHandlers.ofString());
 50	        return new Res(r.statusCode(), r.body());
 51	    }
 52	
 53	    static String booking(int room, String in, String out, int guests, String plan, String extra) {
 54	        return "{\"roomNumber\":" + room + ",\"guestName\":\"Carla Dias\",\"guestEmail\":\"carla@x.com\","
 55	                + "\"guestCpf\":\"111.222.333-44\",\"checkIn\":\"" + in + "\",\"checkOut\":\"" + out
 56	                + "\",\"guests\":" + guests + ",\"ratePlan\":\"" + plan + "\"" + extra + "}";
 57	    }
 58	
 59	    @Test
 60	    void fullFlowWithReceiptAndEmail() throws Exception {
 61	        Res created = send("POST", "/reservations", booking(201, "2027-03-10", "2027-03-12", 2, "STANDARD", ""));
 62	        assertEquals(201, created.status());
 63	        assertEquals("PENDING", created.json().get("status").asText());
 64	        long id = created.json().get("id").asLong();
 65	
 66	        assertEquals(409, send("POST", "/reservations/" + id + "/check-in", null).status());
 67	        assertEquals(409, send("GET", "/reservations/" + id + "/document", null).status());
 68	
 69	        Res confirmed = send("POST", "/reservations/" + id + "/confirmation", null);
 70	        assertEquals(200, confirmed.status());
 71	        assertTrue(confirmed.body().contains("\"amountPaid\":779.80"), confirmed.body());
 72	
 73	        JsonNode message = null;
 74	        for (JsonNode m : send("GET", "/messages", null).json()) {
 75	            if (m.get("body").asText().contains("nº " + id + "\n")) {
 76	                message = m;
 77	            }
 78	        }
 79	        assertEquals("EMAIL", message.get("channel").asText());
 80	        assertEquals("Reserva confirmada - Pousada Maré Alta", message.get("subject").asText());
 81	        assertTrue(message.get("body").asText().contains("Total: R$ 779,80\n\nA entrada é a partir das 14h"));
 82	
 83	        assertEquals(200, send("POST", "/reservations/" + id + "/check-in", null).status());
 84	        Res out = send("POST", "/reservations/" + id + "/check-out", null);
 85	        assertEquals("Comprovante de reserva", out.json().get("title").asText());
 86	        assertEquals(409, send("POST", "/reservations/" + id + "/cancellation", null).status());
 87	    }
 88	
 89	    @Test
 90	    void errors() throws Exception {
 91	        assertEquals(400, send("POST", "/reservations", "nao e json").status());
 92	        assertEquals(400, send("POST", "/reservations", booking(101, "2027-03-10", "2027-03-10", 1, "STANDARD", "")).status());
 93	        assertEquals(400, send("POST", "/reservations", booking(101, "2027-03-10", "2027-03-11", 0, "STANDARD", "")).status());
 94	        assertEquals(404, send("POST", "/reservations", booking(999, "2027-03-10", "2027-03-11", 1, "STANDARD", "")).status());
 95	        assertEquals(422, send("POST", "/reservations", booking(101, "2027-03-10", "2027-03-11", 3, "STANDARD", "")).status());
 96	        assertEquals(400, send("POST", "/reservations", booking(102, "2027-03-10", "2027-03-11", 1, "CORPORATE", "")).status());
 97	        assertEquals(404, send("GET", "/reservations/9999", null).status());
 98	        assertEquals(400, send("GET", "/reports/revenue?month=2027-13", null).status());
 99	        assertEquals("RESERVATION_NOT_FOUND", send("GET", "/reservations/x", null).json().get("error").asText());
100	    }
