102	    @Test
103	    void overlapAndCancellationRefund() throws Exception {
104	        long id = send("POST", "/reservations", booking(301, "2027-03-12", "2027-03-14", 2, "WEEKEND_PACKAGE", ""))
105	                .json().get("id").asLong();
106	        assertEquals(409, send("POST", "/reservations", booking(301, "2027-03-13", "2027-03-15", 2, "STANDARD", "")).status());
107	        send("POST", "/reservations/" + id + "/confirmation", null);
108	        String cancelled = send("POST", "/reservations/" + id + "/cancellation", null).body();
